spec.expr:
100 *
sum by (pod) (
  rate(container_cpu_usage_seconds_total{
    namespace="msa",
    container!="",
    container!="POD"
  }[5m])
)
/
sum by (pod) (
  kube_pod_container_resource_requests{
    namespace="msa",
    resource="cpu"
  }
)

sum by (pod) (
  container_memory_working_set_bytes{
    namespace="msa",
    container!="",
    container!="POD"
  }
)
